export function install(n){Object.assign(n,{lang:function(){const n=document.documentElement.lang;return["ru","en","de"].includes(n)?n:"ru"},text:function(){return n.TEXT[n.lang()]},clock:function(t){try{const e={ru:"ru-RU",en:"en-GB",de:"de-DE"}[n.lang()]||"ru-RU";return new Date(t).toLocaleTimeString(e,{hour:"2-digit",minute:"2-digit"})}catch{return""}}})}